(() => {
  const embeddedData = {"details-TAYLORS.json":"","details-UCSI.json":"","field-answers.json":"","details-SEGI.json":"","search-index.json":"","details-UKM.json":"","details-UPM.json":"","details-UTM.json":"","details-APU.json":"","details-CITY.json":"","details-USM.json":"","details-UM.json":"","details-INTI.json":"","details-UNM.json":"","details-MUM.json":""};
  let catalogPromise, answersPromise;
  const details = new Map();
  const detailBundles = new Map();
  const version = new URL(document.currentScript.src).searchParams.get('v');
  async function json(path) {
    const encoded = embeddedData[path.split('/').pop()];
    if (!encoded) throw new Error('资料文件不存在，请刷新页面。');
    const bytes = Uint8Array.from(atob(encoded), char => char.charCodeAt(0));
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
    return JSON.parse(await new Response(stream).text());
  }
  function catalog() {
    if (!catalogPromise) catalogPromise = json('/data/search-index.json').then(data => {
      window.knowledgeDataDate = data.exported_at;
      return data;
    }).catch(error => { catalogPromise = null; throw error; });
    return catalogPromise;
  }
  function answers() {
    if (!answersPromise) answersPromise = json('/data/field-answers.json').catch(error => { answersPromise = null; throw error; });
    return answersPromise;
  }
  window.hostedKB = async url => {
    const parsed = new URL(url, location.origin), data = await catalog();
    if (parsed.pathname === '/api/search') {
      const rows = knowledgeSearch(data, parsed.searchParams.get('q') || '', Object.fromEntries(parsed.searchParams));
      if (rows[0]?.requested_field) {
        const byFile = await answers();
        for (const row of rows) row.answer = byFile[row.file_path]?.[row.requested_field] ?? '';
      }
      return rows;
    }
    if (parsed.pathname === '/api/programme') {
      const file = parsed.searchParams.get('file'), row = data.programmes.find(item => item.file_path === file);
      if (!row) throw new Error('专业不存在，请刷新页面。');
      if (!details.has(file)) {
        if (!detailBundles.has(row.detail_file)) detailBundles.set(row.detail_file, json('/data/' + row.detail_file).catch(error => { detailBundles.delete(row.detail_file); throw error; }));
        const bundle = await detailBundles.get(row.detail_file);
        if (!bundle[file]) throw new Error('专业详情不存在，请刷新页面。');
        details.set(file, bundle[file]);
      }
      return { ...details.get(file), ...row };
    }
    throw new Error('查询地址无效。');
  };
})();
